def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out."""
    # Simple approach: find first difference and determine what needs to change
    if s_in == s_out:
        return None

    # Find the first position where they differ
    pos = 0
    while pos < len(s_in) and pos < len(s_out) and s_in[pos] == s_out[pos]:
        pos += 1

    if pos >= len(s_in) or pos >= len(s_out):
        # One string is prefix of other
        if len(s_in) < len(s_out):
            return (s_in[pos:], s_out[pos:], pos)
        else:
            return (s_in[pos:], s_out[pos:], pos)

    # Find the longest substring that needs to be replaced
    # For simplicity, we'll look at the difference
    old_sub = s_in[pos:]
    new_sub = s_out[pos:]

    # Actually, let's be more precise - find where the strings diverge
    # and figure out what was inserted/deleted
    i = 0
    while i < len(s_in) and i < len(s_out) and s_in[i] == s_out[i]:
        i += 1

    # Now we know they start the same until position i
    # Let's see if we can find a pattern
    if len(s_in) > len(s_out):
        # Deletion occurred
        old_sub = s_in[i:i+len(s_in)-len(s_out)+1]
        new_sub = ""
    elif len(s_in) < len(s_out):
        # Insertion occurred  
        old_sub = ""
        new_sub = s_out[i:i+len(s_out)-len(s_in)+1]
    else:
        # Same length, just substitution
        old_sub = s_in[i]
        new_sub = s_out[i]

    return (old_sub, new_sub, i)

